module HarmonicSum(\n    input [9:0] n,\n    output [63:0] result\n);\n    reg [63:0] sum;\n    reg [63:0] product;\n    integer i;\n\n    always @* begin\n        sum = 64'd0;\n        for (i = 1; i <= 1000; i = i + 1) begin\n            if (i <= n) begin\n                sum = sum + (64'd4294967296 / i);\n            end\n        end\n        product = sum * {54'd0, n};\n    end\n\n    assign result = product;\nendmodule